{"content":""""Small statistics helpers."""


def mean(xs):
    """Return the float mean of ``xs``, or 0.0 for an empty sequence.

    Raises TypeError if ``xs`` is not iterable.
    """
    values = list(xs)
    if not values:
        return 0.0
    return float(sum(values)) / float(len(values))
